import { db, brandsTable, brandAssetsTable } from "@workspace/db";
import { eq } from "drizzle-orm";
import { ObjectStorageService } from "./objectStorage";
import { logger } from "./logger";

/**
 * Idempotent sync of the brand library from Auckland Council's public
 * Frontify portal (the "live source of truth" pattern): new portal assets are
 * downloaded into object storage and registered as brand_assets; existing
 * ones (matched by folder + name) are left untouched, so admin edits survive.
 *
 * Access is Frontify's guest flow: GET the portal page for session cookies,
 * then hit /api/assets/search/<docId> with those cookies AND a Referer header
 * (401 without it). Flat libraries return assets in data[]; document
 * libraries nest them in folder groups (data[].assets).
 *
 * Runs are capped (FRONTIFY_SYNC_MAX_NEW, default 100 new assets) so a cron
 * invocation stays well inside serverless time limits; the daily run continues
 * where the last one left off.
 */

const DEFAULT_PORTAL_URL = "https://aucklandcouncil.frontify.com/d/67jM5b5GuoL9";

interface SourceRule {
  docId: number;
  folder: string;
  kind: "logo" | "image" | "file";
  /** Document libraries nest assets inside folder-group objects. */
  nested?: boolean;
  /** Only take these extensions (lowercase); undefined = everything with a CDN URL. */
  exts?: string[];
  /** Convert these vector/print formats to PNG at the given width. */
  convertToPng?: { exts: string[]; width: number };
  /** Width hint for raster downloads (photography masters are huge). */
  rasterWidth?: number;
}

// Library document ids discovered from the portal (stable since the 2026-07
// import). Folders must match the names already used in brand_assets.
const SOURCES: SourceRule[] = [
  { docId: 12, folder: "Logos", kind: "logo", convertToPng: { exts: ["ai", "eps", "tif", "tiff"], width: 1200 }, rasterWidth: 1200 },
  { docId: 13, folder: "Photography", kind: "image", exts: ["jpg", "jpeg", "png"], rasterWidth: 1600 },
  { docId: 18, folder: "Illustrations", kind: "image", exts: ["svg", "png", "jpg", "jpeg"] },
  { docId: 33, folder: "Icon graphics", kind: "image", exts: ["svg", "png", "jpg", "jpeg"] },
  { docId: 34, folder: "Kotahitanga patterns", kind: "image", exts: ["svg", "png", "jpg", "jpeg"] },
  { docId: 16, folder: "Video templates", kind: "file" },
  { docId: 17, folder: "Guideline documents", kind: "file", nested: true },
  { docId: 23, folder: "Signage templates", kind: "file", nested: true },
];

const IMAGE_EXTS = new Set(["png", "jpg", "jpeg", "gif", "webp", "svg"]);

// Archive bundles (logo packs etc.) are portal conveniences, not usable assets.
const SKIP_EXTS = new Set(["zip", "rar", "7z"]);

/** Portal titles occasionally arrive percent-encoded; stored names must not be. */
function cleanTitle(title: string): string {
  try {
    return decodeURIComponent(title);
  } catch {
    return title;
  }
}

const EXT_CONTENT_TYPES: Record<string, string> = {
  png: "image/png",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  gif: "image/gif",
  webp: "image/webp",
  svg: "image/svg+xml",
  pdf: "application/pdf",
  mp4: "video/mp4",
  ai: "application/postscript",
  eps: "application/postscript",
  indd: "application/octet-stream",
};

interface FrontifyAsset {
  title?: string;
  ext?: string;
  generic_url?: string;
}

export interface FrontifySyncResult {
  ok: boolean;
  brand?: string;
  scanned: number;
  known: number;
  added: number;
  skipped: number;
  /** New assets seen but not fetched because the per-run cap was reached. */
  deferred: number;
  addedNames: string[];
  errors: string[];
}

async function establishGuestSession(portalUrl: string): Promise<string> {
  const res = await fetch(portalUrl, { redirect: "follow" });
  if (!res.ok) {
    throw new Error(`Portal page returned ${res.status}`);
  }
  const cookies = res.headers.getSetCookie();
  return cookies.map((c) => c.split(";")[0]).join("; ");
}

async function fetchLibraryPage(
  origin: string,
  portalUrl: string,
  cookie: string,
  docId: number,
  page: number,
): Promise<{ items: FrontifyAsset[]; hasMore: boolean }> {
  const res = await fetch(`${origin}/api/assets/search/${docId}?limit=100&page=${page}`, {
    headers: { Referer: portalUrl, Cookie: cookie, Accept: "application/json" },
  });
  if (!res.ok) {
    throw new Error(`assets/search/${docId} page ${page} returned ${res.status}`);
  }
  const body = (await res.json()) as {
    success?: boolean;
    hasMore?: boolean;
    data?: Array<FrontifyAsset & { assets?: FrontifyAsset[] }>;
  };
  if (!body.success || !Array.isArray(body.data)) {
    return { items: [], hasMore: false };
  }
  const first = body.data[0];
  const items =
    first && Array.isArray(first.assets)
      ? body.data.flatMap((group) => group.assets ?? [])
      : (body.data as FrontifyAsset[]);
  return { items, hasMore: !!body.hasMore };
}

/** Resolve download URL + final extension for an asset under a source rule. */
function resolveDownload(
  asset: FrontifyAsset,
  rule: SourceRule,
): { url: string; finalExt: string } | null {
  const ext = (asset.ext || "").toLowerCase();
  const genericUrl = asset.generic_url;
  if (!genericUrl || !ext) {
    return null; // FILE-type portal assets (mogrt etc.) have no CDN URL
  }
  if (rule.convertToPng && rule.convertToPng.exts.includes(ext)) {
    return {
      url: `${genericUrl.replace("{width}", String(rule.convertToPng.width))}&format=png`,
      finalExt: "png",
    };
  }
  if (rule.rasterWidth && ["png", "jpg", "jpeg", "webp"].includes(ext)) {
    return { url: genericUrl.replace("{width}", String(rule.rasterWidth)), finalExt: ext };
  }
  // Everything else (svg, pdf, mp4, raw .ai, …) downloads verbatim.
  return { url: genericUrl.split("?")[0], finalExt: ext };
}

export async function runFrontifySync(): Promise<FrontifySyncResult> {
  const portalUrl = process.env.FRONTIFY_PORTAL_URL || DEFAULT_PORTAL_URL;
  const brandName = process.env.FRONTIFY_BRAND_NAME || "Auckland Council";
  const maxNew = Number(process.env.FRONTIFY_SYNC_MAX_NEW || 100);
  const origin = new URL(portalUrl).origin;
  // Optional folder allowlist (comma-separated). The portal's photography doc
  // alone holds ~2000 masters, so which folders track the portal is a choice.
  const sourceFilter = (process.env.FRONTIFY_SYNC_SOURCES || "")
    .split(",")
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);
  const sources = sourceFilter.length
    ? SOURCES.filter((s) => sourceFilter.includes(s.folder.toLowerCase()))
    : SOURCES;

  const result: FrontifySyncResult = {
    ok: true,
    scanned: 0,
    known: 0,
    added: 0,
    skipped: 0,
    deferred: 0,
    addedNames: [],
    errors: [],
  };

  const [brand] = await db.select().from(brandsTable).where(eq(brandsTable.name, brandName));
  if (!brand) {
    return { ...result, ok: false, errors: [`Brand "${brandName}" not found`] };
  }
  result.brand = brand.name;

  const cookie = await establishGuestSession(portalUrl);
  const storage = new ObjectStorageService();

  const existingRows = await db
    .select({ name: brandAssetsTable.name, folder: brandAssetsTable.folder })
    .from(brandAssetsTable)
    .where(eq(brandAssetsTable.brandId, brand.id));
  const existing = new Set(existingRows.map((r) => `${r.folder ?? ""}�${r.name}`));

  for (const rule of sources) {
    try {
      let page = 1;
      let hasMore = true;
      while (hasMore && page <= 30) {
        const { items, hasMore: more } = await fetchLibraryPage(origin, portalUrl, cookie, rule.docId, page);
        hasMore = more && items.length > 0;
        page += 1;

        for (const asset of items) {
          result.scanned += 1;
          const ext = (asset.ext || "").toLowerCase();
          if (SKIP_EXTS.has(ext) || (rule.exts && !rule.exts.includes(ext))) {
            result.skipped += 1;
            continue;
          }
          const download = resolveDownload(asset, rule);
          if (!download || !asset.title) {
            result.skipped += 1;
            continue;
          }
          const name = `${cleanTitle(asset.title)}.${download.finalExt}`;
          const key = `${rule.folder}�${name}`;
          if (existing.has(key)) {
            result.known += 1;
            continue;
          }
          if (result.added >= maxNew) {
            result.deferred += 1;
            continue;
          }
          try {
            const res = await fetch(download.url, { headers: { Referer: portalUrl } });
            if (!res.ok) {
              throw new Error(`download ${res.status}`);
            }
            const buffer = Buffer.from(await res.arrayBuffer());
            const contentType = EXT_CONTENT_TYPES[download.finalExt] || "application/octet-stream";
            const objectPath = await storage.uploadBytes(buffer, contentType);
            // Non-image files are "file" tiles regardless of source — a PDF in
            // the Logos doc must never become a pickable logo.
            const kind = !IMAGE_EXTS.has(download.finalExt)
              ? "file"
              : rule.kind === "logo"
                ? "logo"
                : "image";
            await db.insert(brandAssetsTable).values({
              brandId: brand.id,
              name,
              kind,
              folder: rule.folder,
              objectPath,
              contentType,
            });
            existing.add(key);
            result.added += 1;
            result.addedNames.push(`${rule.folder}/${name}`);
          } catch (err) {
            result.errors.push(`${rule.folder}/${name}: ${err instanceof Error ? err.message : String(err)}`);
          }
        }
      }
    } catch (err) {
      result.errors.push(`doc ${rule.docId} (${rule.folder}): ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  logger.info(
    { added: result.added, known: result.known, deferred: result.deferred, errors: result.errors.length },
    "Frontify sync finished",
  );
  return result;
}
